insert into assets.asset_categories(id,tenant_id,code,name) values('b2000000-0000-7000-8000-000000000001','b0000000-0000-7000-8000-000000000001','LIFT','Lift');
insert into assets.assets(id,tenant_id,category_id,property_id,scope,asset_code,name) values('b3000000-0000-7000-8000-000000000001','b0000000-0000-7000-8000-000000000001','b2000000-0000-7000-8000-000000000001','b1000000-0000-7000-8000-000000000001','property','LIFT-01','Test Lift');
insert into maintenance.work_orders(id,tenant_id,property_id,asset_id,title) values('b4000000-0000-7000-8000-000000000001','b0000000-0000-7000-8000-000000000001','b1000000-0000-7000-8000-000000000001','b3000000-0000-7000-8000-000000000001','Lift inspection');
insert into maintenance.work_order_checklist_items(id,tenant_id,work_order_id,sequence_no,label) values('b5000000-0000-7000-8000-000000000001','b0000000-0000-7000-8000-000000000001','b4000000-0000-7000-8000-000000000001',1,'Safety check');
select lives_ok($$update maintenance.work_orders set status='scheduled' where id='b4000000-0000-7000-8000-000000000001'$$,'work order scheduled');
select lives_ok($$update maintenance.work_orders set status='in_progress' where id='b4000000-0000-7000-8000-000000000001'$$,'work order started');
select throws_like($$update maintenance.work_orders set status='completed' where id='b4000000-0000-7000-8000-000000000001'$$,'%required_checklist_items_incomplete%','incomplete checklist blocks completion');
update maintenance.work_order_checklist_items set completed=true,completed_at=statement_timestamp() where id='b5000000-0000-7000-8000-000000000001';
select lives_ok($$update maintenance.work_orders set status='completed' where id='b4000000-0000-7000-8000-000000000001'$$,'completed after checklist');
select lives_ok($$update maintenance.work_orders set status='verified' where id='b4000000-0000-7000-8000-000000000001'$$,'completed work verified');
select throws_like($$update maintenance.work_orders set status='scheduled' where id='b4000000-0000-7000-8000-000000000001'$$,'%invalid_work_order_transition%','invalid transition rejected');
insert into portfolio.parties(id,tenant_id,type,legal_name) values('b6000000-0000-7000-8000-000000000001','b0000000-0000-7000-8000-000000000001','company','Maintenance Test Vendor');
insert into maintenance.vendors(id,tenant_id,party_id,status) values('b7000000-0000-7000-8000-000000000001','b0000000-0000-7000-8000-000000000001','b6000000-0000-7000-8000-000000000001','approved');
insert into maintenance.purchase_orders(id,tenant_id,work_order_id,vendor_id,subtotal,tax_total,snapshot_json) values('b8000000-0000-7000-8000-000000000001','b0000000-0000-7000-8000-000000000001','b4000000-0000-7000-8000-000000000001','b7000000-0000-7000-8000-000000000001',100,19,'{"scope":"test"}'::jsonb);
select lives_ok($$update maintenance.purchase_orders set status='approved' where id='b8000000-0000-7000-8000-000000000001'$$,'purchase order approved');
select lives_ok($$update maintenance.purchase_orders set status='ordered' where id='b8000000-0000-7000-8000-000000000001'$$,'purchase order ordered');
select throws_like($$update maintenance.purchase_orders set subtotal=101 where id='b8000000-0000-7000-8000-000000000001'$$,'%approved_purchase_order_is_immutable%','approved PO amount immutable');
select lives_ok($$update maintenance.purchase_orders set status='received' where id='b8000000-0000-7000-8000-000000000001'$$,'purchase order received');
select throws_like($$update maintenance.purchase_orders set status='cancelled' where id='b8000000-0000-7000-8000-000000000001'$$,'%approved_purchase_order_is_immutable%','received PO immutable');
select * from finish();
rollback;
